import inspect

def _verify(iface, candidate, tentative=False, vtype=None):
    errors = []

    if not tentative and not iface.providedBy(candidate):
        errors.append(f"Candidate does not claim to provide the interface {iface}")

    required_methods = set(iface.names(True))
    candidate_methods = set(dir(candidate))

    missing_methods = required_methods - candidate_methods
    for method_name in missing_methods:
        errors.append(f"Missing method: {method_name}")

    for method_name in required_methods:
        if method_name in candidate_methods:
            required_signature = inspect.signature(getattr(iface, method_name))
            candidate_method = getattr(candidate, method_name)
            candidate_signature = inspect.signature(candidate_method)
            if required_signature!= candidate_signature:
                errors.append(f"Incorrect signature for method {method_name}: expected {required_signature}, got {candidate_signature}")

    required_attributes = set(attr for attr in iface.names(True) if not callable(getattr(iface, attr)))
    missing_attributes = required_attributes - candidate_methods
    for attr_name in missing_attributes:
        errors.append(f"Missing attribute: {attr_name}")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True

