def verifyObject(iface, candidate, tentative=False):
    errors = []

    if not tentative and not iface.providedBy(candidate):
        errors.append(f"Candidate does not claim to provide {iface}")

    required_methods = set(iface.names(True))
    candidate_methods = set(dir(candidate))

    missing_methods = required_methods - candidate_methods
    if missing_methods:
        errors.extend([f"Missing method: {method}" for method in missing_methods])

    for method_name in required_methods.intersection(candidate_methods):
        method = getattr(iface, method_name)
        candidate_method = getattr(candidate, method_name)
        try:
            sig_method = signature(method)
            sig_candidate = signature(candidate_method)
            if sig_method!= sig_candidate:
                errors.append(f"Incorrect signature for {method_name}: expected {sig_method}, got {sig_candidate}")
        except TypeError:
            pass  # Skip if method is not callable

    required_attributes = set(attr for attr in iface.names(True) if not callable(getattr(iface, attr)))
    missing_attributes = required_attributes - candidate_methods
    if missing_attributes:
        errors.extend([f"Missing attribute: {attr}" for attr in missing_attributes])

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True

