def lfu_cache(maxsize=128, typed=False):
    cache = {}
    freq = defaultdict(int)
    key_to_freq = {}

    def wrapper(*args, **kwargs):
        key = args if not typed else (args, tuple(sorted(kwargs.items())))
        if key in cache:
            freq[key] += 1
            return cache[key]
        result = func(*args, **kwargs)
        if len(cache) >= maxsize:
            lfu_key = min(cache, key=lambda k: (freq[k], key_to_freq[k]))
            del cache[lfu_key]
            del freq[lfu_key]
            del key_to_freq[lfu_key]
        cache[key] = result
        freq[key] = 1
        key_to_freq[key] = len(key_to_freq)
        return result

    def func(*args, **kwargs):
        return wrapper(*args, **kwargs)

    return wrapper

def popitem(self):
