class Time:
    @classmethod
    def from_ticks(cls, ticks, tz=None):
        if not (0 <= ticks < 86400000000000):
            raise ValueError("ticks is out of bounds")
        seconds = ticks // 1_000_000_000
        microseconds = (ticks % 1_000_000_000) // 1_000
        delta = timedelta(seconds=seconds, microseconds=microseconds)
        naive_time = (datetime.min + delta).time()
        return cls(naive_time.replace(tzinfo=tz) if tz else naive_time)

